#!/usr/bin/env bash
# Restore script for Sony BRAVIA 4K VH21 (KD-65X85K)
# Generated by CleanYourTV process
TV_HOST=${TV_HOST:?set TV_HOST}
PY=$(dirname "$0")/tools/venv/bin/python
[ -x "$PY" ] || PY=$(dirname "$0")/tools/venv/bin/python3
[ -x "$PY" ] || PY=$(dirname "$0")/tools/venv/Scripts/python.exe

# Re-enable disabled packages
for pkg in tv.samba.ssm tv.samba.ssm.ui com.sonyericsson.idd.agent com.sony.dtv.usercontext com.qterics.da.product com.sony.dtv.da.service com.google.android.feedback com.sony.dtv.promos com.sony.dtv.sonyselect com.sony.dtv.sonytab com.sony.dtv.demosupport com.sony.dtv.demosystemsupport com.sony.dtv.multiscreendemo com.uei.quicksetsdk.sony com.google.android.tts com.sony.dtv.seeds.iot com.sony.dtv.gestureapp com.google.android.tungsten.setupwraith; do
  TV_HOST=$TV_HOST "$PY" -I $(dirname "$0")/tools/tv.py "pm enable --user 0 $pkg" 2>/dev/null || true
done

# Restore stock launcher
TV_HOST=$TV_HOST "$PY" -I $(dirname "$0")/tools/tv.py "pm enable --user 0 com.google.android.apps.tv.launcherx" 2>/dev/null || true
TV_HOST=$TV_HOST "$PY" -I $(dirname "$0")/tools/tv.py "cmd package set-home-activity --user 0 \$(TV_HOST=$TV_HOST '$PY' -I $(dirname "$0")/tools/tv.py 'cmd package resolve-activity --brief -a android.intent.action.MAIN -c android.intent.category.HOME com.google.android.apps.tv.launcherx' | tail -n 1)" 2>/dev/null || true

echo "Restore attempted. Reboot recommended."
